with parsed as (select id, plan, effective_from, tier_limits, tier_prices, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, array_min(tier_prices) as lowest_price from price_tiers) select id, plan, sum(lowest_price) over (partition by plan order by lowest_price, id rows between unbounded preceding and current row) as running_sum_lowest_price, count(lowest_price) over (partition by plan order by lowest_price, id rows between unbounded preceding and current row) as running_count_lowest_price, min(lowest_price) over (partition by plan order by lowest_price, id rows between unbounded preceding and current row) as running_min_lowest_price, avg(lowest_price) over (partition by plan order by lowest_price, id rows between unbounded preceding and current row) as running_avg_lowest_price from parsed
